import React, { useState } from "react";
import { motion } from "framer-motion";

const Login = () => {
  const [form, setForm] = useState({ email: "", password: "" });

  return (
    <motion.div
      className="min-h-[80vh] flex flex-col items-center justify-center text-center p-6"
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <h1 className="text-3xl font-bold mb-4 text-blue-400">Login</h1>
      <form className="bg-blue-950/60 border border-blue-800 p-8 rounded-xl shadow-lg w-full max-w-sm">
        <input
          type="email"
          placeholder="Email"
          className="w-full mb-4 p-2 rounded bg-blue-900 text-white border border-blue-700 focus:ring-2 focus:ring-blue-400 outline-none"
          onChange={(e) => setForm({ ...form, email: e.target.value })}
        />
        <input
          type="password"
          placeholder="Password"
          className="w-full mb-4 p-2 rounded bg-blue-900 text-white border border-blue-700 focus:ring-2 focus:ring-blue-400 outline-none"
          onChange={(e) => setForm({ ...form, password: e.target.value })}
        />
        <button className="w-full bg-blue-500 py-2 rounded hover:bg-blue-600 transition-all">
          Login
        </button>
      </form>
    </motion.div>
  );
};

export default Login;
